import type { TelegramClient } from "telegram";

type TelegramEntity = Parameters<TelegramClient["sendMessage"]>[0];

const MAX_TELEGRAM_MESSAGE_LENGTH = 4_000;
const trackedServiceMessages = new Set<string>();

function key(chatId: unknown, messageId: unknown): string | null {
  if (chatId == null || messageId == null) return null;
  return `${String(chatId)}:${String(messageId)}`;
}

/** Prevent output generated by this process from being interpreted as a new command. */
export function registerServiceMessage(message: { id?: number; chatId?: unknown }, chatId?: unknown): void {
  const messageKey = key(chatId ?? message.chatId, message.id);
  if (!messageKey) return;
  trackedServiceMessages.add(messageKey);
  if (trackedServiceMessages.size > 2_000) {
    const oldest = trackedServiceMessages.values().next().value;
    if (oldest) trackedServiceMessages.delete(oldest);
  }
}

export function consumeServiceMessage(chatId: unknown, messageId: unknown): boolean {
  const messageKey = key(chatId, messageId);
  if (!messageKey || !trackedServiceMessages.has(messageKey)) return false;
  trackedServiceMessages.delete(messageKey);
  return true;
}

function splitForTelegram(text: string): string[] {
  const chars = Array.from(text);
  if (chars.length <= MAX_TELEGRAM_MESSAGE_LENGTH) return [text];

  const chunks: string[] = [];
  let offset = 0;
  while (offset < chars.length) {
    let end = Math.min(offset + MAX_TELEGRAM_MESSAGE_LENGTH, chars.length);
    if (end < chars.length) {
      const boundary = chars.slice(offset, end).findLastIndex((char) => char === "\n" || char === " ");
      if (boundary > 0) end = offset + boundary + 1;
    }
    chunks.push(chars.slice(offset, end).join("").trim());
    offset = end;
  }
  return chunks.filter(Boolean);
}

export async function sendLlmResponse(
  client: TelegramClient,
  chatId: TelegramEntity,
  text: string,
  replyTo?: number,
): Promise<void> {
  for (const chunk of splitForTelegram(text)) {
    const sent = await client.sendMessage(chatId, {
      message: chunk,
      ...(replyTo ? { replyTo } : {}),
    });
    registerServiceMessage(sent, chatId);
  }
}
